To convert GPX (GPS Exchange Format) files to JSON in Python, you can use the `gpxpy` library along with Python's built-in `json` module. Here's a comprehensive guide with examples:

## Installation

First, install the required library:
```bash
pip install gpxpy
```

## Basic GPX to JSON Conversion

```python
import gpxpy
import json

# Read GPX file
with open('sample.gpx', 'r') as gpx_file:
    gpx = gpxpy.parse(gpx_file)

# Create dictionary structure
data = []

for track in gpx.tracks:
    for segment in track.segments:
        for point in segment.points:
            data.append({
                'latitude': point.latitude,
                'longitude': point.longitude,
                'elevation': point.elevation,
                'time': point.time.isoformat() if point.time else None
            })

# Convert to JSON
json_output = json.dumps(data, indent=2)
print(json_output)
```

**Output:**
```json
[
  {
    "latitude": 45.12345,
    "longitude": -122.67890,
    "elevation": 100.5,
    "time": "2023-06-15T14:30:00"
  },
  {
    "latitude": 45.12350,
    "longitude": -122.67895,
    "elevation": 102.3,
    "time": "2023-06-15T14:31:00"
  }
]
```

## Advanced Conversion with Waypoints and Routes

```python
import gpxpy
import json

def gpx_to_json(gpx_file_path):
    with open(gpx_file_path, 'r') as file:
        gpx = gpxpy.parse(file)

    result = {
        'waypoints': [],
        'tracks': [],
        'routes': []
    }

    # Extract waypoints
    for waypoint in gpx.waypoints:
        result['waypoints'].append({
            'name': waypoint.name,
            'lat': waypoint.latitude,
            'lon': waypoint.longitude,
            'ele': waypoint.elevation,
            'description': waypoint.description
        })

    # Extract tracks
    for track in gpx.tracks:
        track_data = {
            'name': track.name,
            'segments': []
        }
        for segment in track.segments:
            points = []
            for point in segment.points:
                points.append({
                    'lat': point.latitude,
                    'lon': point.longitude,
                    'ele': point.elevation,
                    'time': str(point.time) if point.time else None,
                    'speed': point.speed
                })
            track_data['segments'].append(points)
        result['tracks'].append(track_data)

    # Extract routes
    for route in gpx.routes:
        route_points = []
        for point in route.points:
            route_points.append({
                'lat': point.latitude,
                'lon': point.longitude,
                'ele': point.elevation,
                'name': point.name
            })
        result['routes'].append({
            'name': route.name,
            'points': route_points
        })

    return json.dumps(result, indent=2)

# Usage
json_data = gpx_to_json('trail.gpx')
print(json_data)
```

**Output:**
```json
{
  "waypoints": [
    {
      "name": "Start Point",
      "lat": 47.2345,
      "lon": -121.4567,
      "ele": 500.0,
      "description": "Trail beginning"
    }
  ],
  "tracks": [
    {
      "name": "Morning Hike",
      "segments": [
        [
          {
            "lat": 47.2345,
            "lon": -121.4567,
            "ele": 500.0,
            "time": "2023-06-15 08:00:00",
            "speed": null
          }
        ]
      ]
    }
  ],
  "routes": []
}
```

## Saving JSON to File

```python
import gpxpy
import json

def save_gpx_as_json(gpx_path, json_path):
    with open(gpx_path, 'r') as gpx_file:
        gpx = gpxpy.parse(gpx_file)

    tracks_list = []
    for track in gpx.tracks:
        for segment in track.segments:
            for point in segment.points:
                tracks_list.append({
                    'coordinates': [point.longitude, point.latitude],
                    'elevation': point.elevation,
                    'timestamp': point.time.strftime('%Y-%m-%d %H:%M:%S') if point.time else None
                })

    with open(json_path, 'w') as json_file:
        json.dump({'type': 'FeatureCollection', 'features': tracks_list}, 
                  json_file, indent=4)

    print(f"Conversion complete! JSON saved to {json_path}")

# Execute conversion
save_gpx_as_json('input.gpx', 'output.json')
```

This approach provides flexible GPX to JSON conversion, allowing you to extract specific data points and structure them according to your needs. The resulting JSON can be easily consumed by web applications, APIs, or data analysis tools.

